import java.util.*;

public class MiniRedisList {
    static Map<String, Deque<String>> listy = new HashMap<>();

    static void rpush(String k, String v) { listy.computeIfAbsent(k, x -> new ArrayDeque<>()).addLast(v); }
    static void lpush(String k, String v) { listy.computeIfAbsent(k, x -> new ArrayDeque<>()).addFirst(v); }

    static List<String> lrange(String k, int start, int stop) {
        List<String> l = new ArrayList<>(listy.getOrDefault(k, new ArrayDeque<>()));
        int n = l.size();
        if (start < 0) start = Math.max(0, n + start);
        if (stop < 0) stop = n + stop;
        stop = Math.min(stop, n - 1);
        return start > stop ? List.of() : l.subList(start, stop + 1);
    }

    public static void main(String[] args) {
        rpush("h", "java"); rpush("h", "spring"); lpush("h", "redis");
        System.out.println(lrange("h", 0, -1));   // [redis, java, spring]
        System.out.println(lrange("h", -2, -1));  // [java, spring]
    }
}
Wyniki zgodne z Redis 7.4 (LRANGE h 0 -1 -> redis java spring; LRANGE h -2 -1 -> java spring).

import java.util.*;
import java.util.stream.*;

public class Ranking {
    private final Map<String, Integer> wyniki = new HashMap<>();

    void zincrby(String gracz, int pkt) { wyniki.merge(gracz, pkt, Integer::sum); }

    List<String> top(int n) {
        return posortowane().limit(n).map(e -> e.getKey() + "=" + e.getValue()).toList();
    }

    int pozycja(String gracz) {
        List<String> kolejnosc = posortowane().map(Map.Entry::getKey).toList();
        return kolejnosc.indexOf(gracz) + 1;
    }

    private Stream<Map.Entry<String, Integer>> posortowane() {
        return wyniki.entrySet().stream()
            .sorted(Map.Entry.<String, Integer>comparingByValue().reversed());
    }

    public static void main(String[] args) {
        Ranking r = new Ranking();
        r.zincrby("Jan", 100); r.zincrby("Anna", 300); r.zincrby("Piotr", 200);
        r.zincrby("Jan", 150);
        System.out.println(r.top(3));          // [Anna=300, Jan=250, Piotr=200]
        System.out.println(r.pozycja("Jan"));  // 2
    }
}
// Tu każdy odczyt sortuje wszystko: O(n log n). Sorted Set w Redis utrzymuje elementy
// stale posortowane (skip list), więc ZINCRBY, ZREVRANK i top N kosztują O(log n) (+N).
